import com.silverroom.camera.*;import java.util.*;
public final class MeteringPolicyRegression{
 static void check(boolean b,String n){if(!b)throw new AssertionError(n);System.out.println("PASS "+n);}
 public static void main(String[] args){
  MeteringState state=new MeteringState();check(state.snapshot().mode==0&&!state.snapshot().hasFocus&&state.snapshot().aeX==.5f,"New installs start in global AE without manual points");state.tap(.2f,.7f);MeteringState.Snapshot immutable=state.snapshot();state.move(.8f,.3f);check(immutable.afX==immutable.aeX&&state.snapshot().separated()&&state.snapshot().afX==.2f,"Metering snapshots are immutable and AE movement preserves independent AF");
  state.mode(0);state.mode(2);check(state.snapshot().aeX==.8f&&state.snapshot().aeY==.3f,"Changing AE modes preserves the last manually selected point during this finder session");long revision=state.snapshot().revision;state.focus(.4f,.6f);check(state.snapshot().revision==revision&&state.snapshot().aeX==.8f,"AF-only focus does not invalidate or replace the persistent AE position");state.remap();check(state.snapshot().revision==revision+1&&state.snapshot().aeX==.8f,"Same-sensor digital zoom invalidates area mapping while retaining normalized point positions");state.resetPoints();check(!state.snapshot().hasFocus&&state.snapshot().mode==2&&state.snapshot().aeX==.5f,"Leaving the session keeps the chosen mode and resets both points to a clean center");
  boolean geometry=true,extent=true;for(float mm:new float[]{14,23,35,50,85,135,230})for(int pose:new int[]{0,90,180,270})for(int[] viewport:new int[][]{{300,400},{300,300},{300,450},{300,533}})for(float crop:new float[]{1,LensPlan.crop(mm)})for(float x:new float[]{0,.5f,1})for(float y:new float[]{0,.5f,1}){int[] r=MeteringGeometry.region(2,x,y,pose,4000,3000,viewport[0],viewport[1],crop,false,10,20,4000,3000);geometry&=r[0]>=10&&r[1]>=20&&r[2]>0&&r[3]>0&&r[0]+r[2]<=4010&&r[1]+r[3]<=3020;int[] center=MeteringGeometry.region(1,x,y,pose,4000,3000,viewport[0],viewport[1],crop,false,10,20,4000,3000);extent&=center[2]>r[2]&&center[3]>r[3];}check(geometry&&extent,"Seven focal lengths, four sensor rotations, four aspect viewports and edge points produce bounded AE regions");
  int[] r=MeteringGeometry.region(2,.25f,.75f,90,4000,3000,300,400,1,false,0,0,4000,3000);check(r[0]==2850&&r[1]==2100&&r[2]==300&&r[3]==300,"A visible 10-percent short-edge spot maps to the expected sensor center and square extent");
  int[] a=MeteringGeometry.region(1,.1f,.9f,90,4000,3000,300,400,1,false,0,0,4000,3000),b=MeteringGeometry.region(1,.9f,.1f,90,4000,3000,300,400,1,false,0,0,4000,3000);check(Arrays.equals(a,b)&&a[2]==2000&&a[3]==1500,"Central AE ignores manual coordinates and measures the visible central 50-percent region");
  state.tap(Float.NaN,Float.POSITIVE_INFINITY);state.move(-2,4);check(state.snapshot().afX==.5f&&state.snapshot().afY==.5f&&state.snapshot().aeX==0&&state.snapshot().aeY==1,"Corrupt and overscroll coordinates are normalized before reaching a native request");
 }
}
